const K = 0.0063; // I = k * L
const data = JSON.parse(msg.payload);
const lux = data.lux; // REAL — from BH1750 via serial

// --- Predicted current from your physics model, using real lux ---
const predictedCurrent = K * lux;

// --- Simulated ground truth (measured current), until a real
//     photodetector + op-amp is added ---
const noise = (Math.random() - 0.5) * 0.1;
const measuredCurrent = Math.max(0, predictedCurrent + noise);
const error = measuredCurrent - predictedCurrent;
const status = Math.abs(error) >= 1.0 ? "FAULT" : "OK";

// --- Simulated V_out, following the same relationship you used
//     for the fake sensor, until BPW34 + TL071 hardware exists ---
const vOut = Math.min(Math.max(predictedCurrent * 0.5 + noise * 0.5, 0), 3.3);

// --- Simulated ambient temperature, until a DHT22 is wired in ---
const temp = Math.round((27 + (Math.random() - 0.5) * 3) * 10) / 10;

msg.payload = JSON.stringify({
    sensor_id: data.sensor_id,
    lux: lux,                         // real
    v_out: Math.round(vOut * 1000) / 1000,     // simulated
    temp: temp,                                 // simulated
    predicted_current: Math.round(predictedCurrent * 1000) / 1000,
    measured_current: Math.round(measuredCurrent * 1000) / 1000, // simulated
    error: Math.round(error * 1000) / 1000,
    status: status,
    timestamp: data.timestamp,
    // optional but useful for your report/demo — makes it easy to prove
    // which fields are real vs. simulated when you're writing things up
    data_source: {
        lux: "real_bh1750",
        v_out: "simulated",
        temp: "simulated",
        measured_current: "simulated"
    }
});
return msg;

let data;
try {
    data = JSON.parse(msg.payload);
} catch (e) {
    node.warn("Rejected malformed payload: " + msg.payload);
    return null;
}

const required = ["sensor_id", "lux", "v_out", "temp", "timestamp"];
for (const f of required) {
    if (!(f in data)) {
        node.warn("Rejected payload missing field: " + f);
        return null;
    }
}

msg.tags = { sensor_id: data.sensor_id };
msg.payload = {
    lux: data.lux,
    v_out: data.v_out,
    temp: data.temp,
    predicted_current: data.predicted_current,
    measured_current: data.measured_current,
    error: data.error,
    status: data.status   // <-- was missing, added here
};

return msg;

const raw = msg.payload.toString().trim();
const match = raw.match(/Lux:\s*([\d.]+)/);
if (!match) {
    return null; // not a lux line — ignore boot/status messages
}

msg.payload = JSON.stringify({
    sensor_id: "team7-real-01",
    lux: parseFloat(match[1]),
    timestamp: new Date().toISOString()
});
return msg;
